def js(v):return json.dumps(v,ensure_ascii=False)
def wc(v):return len(re.findall(r"[\w’'-]+",v,re.UNICODE))
def blog_content(x):
 title,slug,team,source,dest,fields,exception=x; tag=f"For {title.lower()}, {team} connect {source} to {dest}."
 data=[
 ('Define the operating lane',f"Begin only when an observable trigger enters the approved queue. Record which source, version, scope, and time govern the request. Urgency, familiarity, or repeated follow-up can change priority, but they cannot replace evidence or create authority.",f"Write the finish condition before work begins. Completion requires an authorized action in {dest}, accepted ownership of anything open, and an approved communication or receipt. A sent message, uploaded file, or checked task is activity rather than destination proof."),
 ('Build the minimum working record',f"The case record contains {fields}. Add current status, next action, named owner, due time with timezone, evidence link, and customer or stakeholder promise. Stable identifiers should remain consistent across inboxes, spreadsheets, portals, and task systems.",f"Separate observed facts from decisions. A source value needs provenance and time; an approval needs the authorized actor, reason, conditions, and decision time. Link to sensitive evidence in its governed system instead of copying credentials, identity documents, financial data, or private correspondence."),
 ('Use accountable statuses',f"Use received, checking source, ready under rule, awaiting owner, actioned, destination check, confirmed, exception, and reopened. Every waiting state needs a reason code and next-review time. The word pending hides whether evidence, access, a stakeholder response, or a substantive decision is missing.",f"Measure active handling separately from external wait. Escalation clocks should request review rather than silently grant permission or fabricate an outcome. If a deadline passes, preserve the original timestamps and assign recovery instead of backdating the case."),
 ('Keep authority narrower than access',f"An assistant may collect required fields, compare an unambiguous instruction, draft an approved message, prepare a decision packet, execute an authorized step, and verify the result. Owners retain commercial, legal, financial, employment, security, privacy, safety, and policy decisions unless a written rule explicitly delegates them.",f"Use named accounts, multifactor authentication, minimum roles, controlled exports, and periodic access review. A platform button does not establish business authority. Backup assistants and automations inherit the same boundaries, evidence requirements, and stop rules."),
 ('Work the adverse case',f"Rehearse this exception: {exception}. Freeze only the affected action, preserve competing observations with timestamps, and describe the conflict neutrally. Do not overwrite the inconvenient value or choose the option that makes the queue easiest to close.",f"Route a compact packet with the case ID, verified facts, source links, current destination state, deadline, impact, permitted paths, and exact question. After the owner decides, record the authority, update the controlling system, reconcile dependents, and capture a destination receipt."),
 ('Communicate with bounded language',f"An acknowledgment states what arrived, which check comes next, who owns the decision, and when the next update is expected. It avoids implying approval, eligibility, payment, identity, legal effect, or completion before the source and owner support that statement.",f"Use approved templates as starting points and insert only verified case facts. Record delivery results, not merely send events. A failed message needs a reason, approved alternate channel, new owner if appropriate, and connection to the same case history."),
 ('Verify, sample, and improve',f"Open {dest} after the action and compare it with {source}. Check identifiers, version, effective time, owner, status, dependent notifications, and rollback needs. During an outage, use temporary IDs under a reconciliation plan and do not declare completion before posting back to the primary system.",f"Pilot one bounded queue containing ordinary work, missing evidence, an unavailable owner, a cross-shift handoff, and a reopened case. Track verified closures, exception age, destination mismatch, reopen rate, delivery failures, and owner wait with denominators. Ask a second reviewer to reconstruct sampled outcomes."),
]
 intro=f"Published {VISIBLE}. {title} is a bounded operating guide for {team}. It preserves source evidence, separates preparation from authority, and requires destination verification before closure. {tag}"
 secs=[{'heading':h,'paragraphs':[a+' '+tag,b+' '+tag]} for h,a,b in data]
 return intro,secs

def research_content(x):
 title,slug,q,unit,fields,decision=x; tag=f"This analytical checkpoint belongs to {title.lower()} and its unit: {unit}."
 headings=[
 ('Research question and claim boundary',f"Published {VISIBLE}. This study asks {q}. The unit is {unit}. It can describe patterns and control reliability under frozen definitions; it cannot prove causation, certify compliance, rank assistants, or establish an individual outcome."),
 ('Source selection and method',f"Ten authoritative HTTPS sources from NIST, CISA, FTC, GAO, DOL, DOJ, and ISO provide identity, privacy, security, internal-control, recordkeeping, accessibility, and risk context. The method maps identity, provenance, observed state, decision authority, destination action, and verification."),
 ('Population and sampling frame',f"Define the eligible population before extraction and preserve its count. Include ordinary completions, missing evidence, unavailable owners, failed destinations, and reopened work. Use a documented random or systematic sample plus a separately labeled risk supplement; never call a risk sample representative."),
 ('Data model and lineage',f"The proposed record contains {fields}. It also needs source system, definition, time zone, extraction time, transformation, owner, missing-value meaning, correction history, retention rule, and dataset version. A reviewer should trace sampled rows to source and back."),
 ('Findings framework',f"Separate the initiating request, assistant preparation, owner decision, system action, stakeholder communication, and verified outcome. A reminder can be delivered without a decision; a task can close without owner acceptance; a removal ticket can finish while residual access remains."),
 ('Analysis plan',f"Publish population flow, denominators, missingness, distributions, medians, tail measures, and absolute differences. Keep assistant handling distinct from owner, stakeholder, vendor, and system wait. Disclose any model specification, reference groups, diagnostics, and sensitivity tests."),
 ('Bias and alternatives',f"Test selection from excluded failures, missing off-platform events, definition drift, timezone defaults, changed workload, policy releases, outages, and reviewer knowledge of outcomes. A zero count can mean absence or failed detection. Preserve conflicting sources until an owner resolves them."),
 ('Reviewer agreement',f"Give independent reviewers the same source packet and require field-level classes plus uncertainty. Report disagreement on consequential fields, not only an overall rate. Clarify ambiguous definitions and test a fresh blinded sample rather than privately pressuring reviewers to agree."),
 ('Privacy, fairness, and governance',f"Collect only fields required for the stated decision, replace direct identifiers with study keys, restrict the crosswalk, and apply approved retention. Suppress or aggregate small groups where appropriate. Do not infer protected traits, intent, loyalty, or capability from administrative traces."),
 ('Robustness and replication',f"Repeat analysis after restoring eligible missing cases, excluding disrupted periods, and varying only predefined reasonable thresholds. Archive the preregistration, population logic, dictionary, extraction version, exclusions, review worksheet, disagreements, analysis specification, and sensitivities."),
 ('Decision rule and limitations',f"The operational decision is whether to {decision}. Predefine what triggers repair, continued observation, or no change. Local systems, contracts, task mix, policy versions, languages, access boundaries, and missing evidence limit generalization; association does not establish cause."),
]
 return [{'heading':h,'paragraphs':[b+' '+tag,f"For the {h.lower()} checkpoint in {title.lower()}, record the exact source version, observed event, accountable owner, permitted action, destination receipt, unresolved uncertainty, next review time, and correction history. These fields preserve the distinction between evidence and interpretation for independent reconstruction. "+tag],'rows':[{'label':'Unit of analysis','value':unit,'source':'October 13 protocol'},{'label':'Decision use','value':decision,'source':'October 13 protocol'}]} for h,b in headings]

def make_png(path,title,index):
 size=(1672,941);colors=[('#082f49','#38bdf8'),('#172554','#a78bfa'),('#052e2b','#34d399'),('#3f1d2e','#fb7185'),('#1f2937','#f59e0b')];bg,accent=colors[index%5]
 im=Image.new('RGB',size,bg);d=ImageDraw.Draw(im);bold='/System/Library/Fonts/Supplemental/Arial Bold.ttf';reg='/System/Library/Fonts/Supplemental/Arial.ttf';brand=ImageFont.truetype(bold,38);big=ImageFont.truetype(bold,72);foot=ImageFont.truetype(reg,30);margin=110
 d.rounded_rectangle((margin,72,margin+340,84),6,fill=accent);d.text((margin,128),'OUTSOURCING ASSISTANT',font=brand,fill=accent);d.ellipse((size[0]-350,75,size[0]-90,335),outline=accent,width=15);d.line((size[0]-285,205,size[0]-235,255,size[0]-145,150),fill='white',width=18,joint='curve')
 maxw=size[0]-2*margin;lines=[];cur=''
 for word in title.split():
  trial=(cur+' '+word).strip()
  if d.textlength(trial,font=big)<=maxw:cur=trial
  else:lines.append(cur);cur=word
 if cur:lines.append(cur)
 y=390
 for line in lines:d.text((margin,y),line,font=big,fill='white');y+=90
 d.text((margin,850),'Evidence-led delegation • Original editorial graphic',font=foot,fill='#dbeafe')
 info=PngImagePlugin.PngInfo();info.add_text('Title',title);info.add_text('Description','Original OutsourcingAssistant.com editorial graphic: '+title);path.parent.mkdir(parents=True,exist_ok=True);im.save(path,optimize=True,pnginfo=info)

